def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row if v != 0)
    frame = counts.most_common(1)[0][0]
    inner_counts = Counter(v for row in grid for v in row if v not in (0, frame))
    filler = inner_counts.most_common(1)[0][0] if inner_counts else None

    # Find connected components of the non-background, non-filler colors.
    seen = [[False] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, frame, filler) or seen[r][c]:
                continue
            stack = [(r, c)]
            seen[r][c] = True
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if (0 <= ny < h and 0 <= nx < w and not seen[ny][nx]
                            and grid[ny][nx] == color):
                        seen[ny][nx] = True
                        stack.append((ny, nx))
            ys = [y for y, x in cells]
            xs = [x for y, x in cells]
            comps.append((color, min(ys), max(ys), min(xs), max(xs)))

    out = [row[:] for row in grid]
    for i, (color, r1, r2, c1, c2) in enumerate(comps):
        for other, s1, s2, d1, d2 in comps[i + 1:]:
            if color != other:
                continue
            top, bottom = max(r1, s1), min(r2, s2)
            left, right = max(c1, d1), min(c2, d2)
            if top <= bottom:  # aligned horizontally
                for r in range(top, bottom + 1):
                    for c in range(min(c2, d2) + 1, max(c1, d1)):
                        if out[r][c] == 0:
                            out[r][c] = color
            if left <= right:  # aligned vertically
                for c in range(left, right + 1):
                    for r in range(min(r2, s2) + 1, max(r1, s1)):
                        if out[r][c] == 0:
                            out[r][c] = color
    return out
